//! 🧪️ The genuine native overlay folds typed retained originals while the committed Store remains unchanged.
use super::*;
use semio_framework_plugin_tool_run::tool_jobs_tool_machine::OriginalToolOverlayFold;
#[test]fn original_tool_overlay_fold_retains_typed_input_until_native_semantics_and_aliases_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/🛠️tool-machine/🔁️follow/🧪️tests/🔣️.json")).unwrap();
 let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let store=native_store(&mut caller,&mut decoder);let mut fold=OriginalToolOverlayFold::<State,Mutation>::default();let mut visible=store.snapshot_owner();
 for(ordinal,value)in law["operations"].as_array().unwrap().iter().enumerate(){if ordinal==law["typingRun"]["start"].as_u64().unwrap()as usize{for index in 0..65536{for denied in deny(fold.checkpoint_demands(4096,false).unwrap()){let before=fold.diagnostic_cursor(&store).unwrap();turn(&mut caller,&mut decoder,denied,|cx|{assert!(!fold.checkpoint(&store,cx)?);Ok(())});assert_eq!(before,fold.diagnostic_cursor(&store).unwrap());}if turn(&mut caller,&mut decoder,TURN,|cx|fold.checkpoint(&store,cx)){break}assert!(index<65535);}}let mut mutation=Some(Mutation::Zoom{zoom:value.as_f64().unwrap()});let mut source=None;let mut input=None;
  for index in 0..262144{if source.is_none(){turn(&mut caller,&mut decoder,TURN,|cx|{let d=store::os_store::ArtifactMutationSource::<Mutation>::constructor_demand();let g=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let Some((owner,p))=store::os_store::ArtifactMutationSource::admit(&mut mutation,store.owned_mutation_retirement_factory()?,g)?else{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"funded original overlay source admission refused"))};source=Some(owner);Ok(((),p))})?;Ok(())});}else{let owner=source.as_mut().unwrap();turn(&mut caller,&mut decoder,TURN,|cx|{let d=owner.demands(4096)?;let g=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let p=if owner.ready(){owner.take(&mut input,g)?.unwrap_or_default()}else{owner.advance(g)?.progress()};Ok(((),p))})?;Ok(())});}if input.is_some(){break}assert!(index<262143);}
  for index in 0..262144{let demand=fold.demands(&store,4096).unwrap();for denied in deny(demand){let before=fold.diagnostic_cursor(&store).unwrap();turn(&mut caller,&mut decoder,denied,|cx|{let before=cx.retained_progress();assert!(!fold.advance_input(&store,&mut input,ordinal as u32,cx)?);assert_eq!(cx.retained_progress(),before);Ok(())});assert_eq!(before,fold.diagnostic_cursor(&store).unwrap());}if turn(&mut caller,&mut decoder,TURN,|cx|fold.advance_input(&store,&mut input,ordinal as u32,cx)){break}assert!(index<262143,"original input {ordinal}: {:?}",fold.diagnostic_cursor(&store));}assert!(input.is_none());assert_eq!(fold.accepted(),Some(law["accepted"][ordinal].as_bool().unwrap()));assert_eq!(visible.zoom,law["visibleBeforePublish"].as_f64().unwrap());assert_eq!(store.snapshot_ref().zoom,law["committed"].as_f64().unwrap());
  if ordinal==law["typingRun"]["end"].as_u64().unwrap()as usize{for index in 0..65536{for denied in deny(fold.checkpoint_demands(4096,true).unwrap()){let before=fold.diagnostic_cursor(&store).unwrap();turn(&mut caller,&mut decoder,denied,|cx|{assert!(!fold.finish_checkpoint(&store,true,cx)?);Ok(())});assert_eq!(before,fold.diagnostic_cursor(&store).unwrap());}if turn(&mut caller,&mut decoder,TURN,|cx|fold.finish_checkpoint(&store,true,cx)){break}assert!(index<65535);}assert_eq!(fold.private_snapshot().unwrap().zoom,law["typingRun"]["restored"].as_f64().unwrap());}
  let owner=source.as_mut().unwrap();owner.begin_close();for index in 0..262144{if owner.terminal_is_empty(){break}turn(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=owner.close_demand(4096)?;close_original_retained_step(cx,d,|g|owner.close_step(g))?;Ok(())}));assert!(index<262143);}
 }
 for index in 0..262144{if turn(&mut caller,&mut decoder,TURN,|cx|fold.publish(&store,&mut visible,cx)){break}assert!(index<262143);}assert_eq!(visible.zoom,law["visibleAfterPublish"].as_f64().unwrap());
 for index in 0..262144{if turn(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|fold.close_step(&store,cx))){break}assert!(index<262143);}assert!(fold.terminal_is_empty());
 close_visible_and_store(store,visible,&mut caller,&mut decoder);caller.retire(TURN);
}

fn deny(d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut denied=vec![RetainedCloneGrant{maximum_items:0,..TURN}];if d.copy_bytes>0{denied.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..TURN})}if d.capacity_bytes>0{denied.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..TURN})}if d.release_bytes>0{denied.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..TURN})}if d.depth>0{denied.push(RetainedCloneGrant{maximum_depth:d.depth-1,..TURN})}denied}

fn close_visible_and_store(mut store:Box<store::ConfigStore<State,Mutation>>,visible:Arc<State>,caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner){
 let mut alias=Some(visible);let mut retired=None;for index in 0..262144{if alias.is_none()&&retired.is_none(){break}turn(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{if retired.is_some(){let d=semio_framework_value::select_factory_ticket(&mut retired,4096)?.demands();let g=cx.retained_grant();if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(())}let step=cx.with_native_retirement(|control|semio_framework_value::close_factory_ticket_controlled(&mut retired,g,control))?;cx.consume_retained(step.progress())?;cx.consume_fuel(step.progress().copied_items as u64);}else{let d=RetirementDemand{capacity_bytes:semio_framework_value::factory::FactorySharedRetirement::<State>::constructor_capacity_bytes(),depth:2,..Default::default()};close_original_retained_step(cx,d,|g|{let p=store.retire_snapshot_alias(&mut alias,g)?.map_or(Default::default(),|(owner,p)|{retired=Some(owner);p});Ok(RetainedCloneStep::Progress(p))})?;}Ok(())}));assert!(index<262143);}
 for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(caller,decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|g|store.close_owned_store_step(g))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,caller,decoder);while !decoder.terminal_is_empty(){caller.turn(TURN,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}
}
#[test]fn original_tool_overlay_cancels_each_partial_source_without_publishing(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../🧰️framework/🛍️products/💻️os/🔨️modules/🔌️plugin/🛠️tool-machine/🔁️follow/🧪️tests/🔣️.json")).unwrap();
 for zoom in [0.0,8.0]{for cut in law["cancelCuts"].as_array().unwrap(){let mut caller=caller();let mut decoder=OriginalJobDecodeOwner::empty();let store=native_store(&mut caller,&mut decoder);let visible=store.snapshot_owner();let mut fold=OriginalToolOverlayFold::<State,Mutation>::default();let mut mutation=Some(Mutation::Zoom{zoom});let mut source=None;let mut input=None;
 for index in 0..65536{if let Some(owner)=source.as_mut(){let owner:&mut store::os_store::ArtifactMutationSource<Mutation>=owner;turn(&mut caller,&mut decoder,TURN,|cx|{let d=owner.demands(4096)?;let g=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let p=if owner.ready(){owner.take(&mut input,g)?.unwrap_or_default()}else{owner.advance(g)?.progress()};Ok(((),p))})?;Ok(())});}else{turn(&mut caller,&mut decoder,TURN,|cx|{let d=store::os_store::ArtifactMutationSource::<Mutation>::constructor_demand();let g=cx.retained_grant();let mut done=None;admit_original_construction(cx,&mut done,OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth},|_|{let(owner,p)=store::os_store::ArtifactMutationSource::admit(&mut mutation,store.owned_mutation_retirement_factory()?,g)?.unwrap();source=Some(owner);Ok(((),p))})?;Ok(())});}if input.is_some(){break}assert!(index<65535);}
 for index in 0..65536{if turn(&mut caller,&mut decoder,TURN,|cx|fold.checkpoint(&store,cx)){break}assert!(index<65535);} for _ in 0..cut.as_u64().unwrap(){turn(&mut caller,&mut decoder,TURN,|cx|fold.advance_input(&store,&mut input,0,cx));}
 if cut.as_u64().unwrap()>0{let before=fold.diagnostic_cursor(&store).unwrap();let mut foreign=OriginalJobDecodeOwner::empty();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.turn_with_decoder(TURN,&mut foreign,|cx|fold.advance_input(&store,&mut input,0,cx)));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(fold.diagnostic_cursor(&store).unwrap(),before);assert!(foreign.terminal_is_empty());}
 caller.cancel().cancel_now();for index in 0..65536{let d=fold.close_demands(&store,4096).unwrap();for denied in deny(d){let before=fold.diagnostic_cursor(&store).unwrap();turn(&mut caller,&mut decoder,denied,|cx|cx.with_original_retirement(|cx|fold.close_step(&store,cx)));assert_eq!(caller.receipt(),Default::default());assert_eq!(fold.diagnostic_cursor(&store).unwrap(),before);}if turn(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|fold.close_step(&store,cx))){break}assert!(index<65535,"original overlay retained cancellation source: {:?}",fold.diagnostic_cursor(&store));}assert!(fold.terminal_is_empty());assert_eq!(visible.zoom,1.25);assert_eq!(store.snapshot_ref().zoom,1.25);
 if let Some(input)=input.as_mut(){for index in 0..65536{if input.terminal_is_empty(){break}turn(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=input.close_demand(4096)?;close_original_retained_step(cx,d,|g|input.close_step(g))?;Ok(())}));assert!(index<65535)}}drop(input);
 let owner=source.as_mut().unwrap();owner.begin_close();for index in 0..65536{if owner.terminal_is_empty(){break}turn(&mut caller,&mut decoder,TURN,|cx|cx.with_original_retirement(|cx|{let d=owner.close_demand(4096)?;close_original_retained_step(cx,d,|g|owner.close_step(g))?;Ok(())}));assert!(index<65535)}close_visible_and_store(store,visible,&mut caller,&mut decoder);caller.retire(TURN);
 }
}
}
